def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Returns an empty string when the key is absent. The text is a
    parameter; this function does not read files.
    """
    for raw in text.splitlines():
        name, sep, value = raw.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_returns_value_for_key() -> None:
    assert config_value("a=1\nb=2", "b") == "2"


def test_missing_key_returns_empty_string() -> None:
    assert config_value("a=1", "z") == ""


def test_empty_text_returns_empty_string() -> None:
    assert config_value("", "a") == ""


def test_strips_whitespace_around_name_and_value() -> None:
    assert config_value("  name =  Ada  ", "name") == "Ada"


def test_value_may_contain_equals_sign() -> None:
    assert config_value("url=http://x?a=b", "url") == "http://x?a=b"


def test_key_match_is_exact_not_prefix() -> None:
    assert config_value("name_full=Ada", "name") == ""
